class Widget {
    int offset;
    void standard_call() {}
    virtual void virt_call() {}
};

// PMF for Non-Virtual (often stored as raw address)
typedef void (Widget::*PMF_NV)();
PMF_NV p_nv = &Widget::standard_call;
// sizeof(PMF_NV) typically == sizeof(void*)

// PMF for Virtual (needs V-table index or lookup thunk)
// Compiler structure: { fn_addr/vtable_index, 'this' adjustment offset }
typedef void (Widget::*PMF_V)();
PMF_V p_v = &Widget::virt_call;
// sizeof(PMF_V) typically > sizeof(void*)

// Dispatch mechanism:
// Compiler uses metadata in PMF structure to adjust 'this' pointer
// (especially for multiple inheritance) before jumping to target function.
Widget w;
(w.*p_nv)();
(w.*p_v)();
